def current_lang():
    code = request.cookies.get("lang", "") if has_request_context() else ""
    if code in LANGS: return code
    header = request.headers.get("Accept-Language", "").lower() if has_request_context() else ""
    for code in ("sr", "en", "ru"):  # по умолчанию русский; сербский или английский, если браузер явно просит
        if header.startswith(code) or header.startswith("hr") and code == "sr" or header.startswith("bs") and code == "sr":
            return code
    return "ru"

def t(key, **params):
    lang = g.get("lang", "ru") if has_request_context() else "ru"
    values = S.get(key)
    text = values[LANGS.index(lang)] if values else key
    if params:
        try: text = text.format(**params)
        except (KeyError, IndexError, ValueError): pass
    return text

def js_strings():
    i = LANGS.index(g.get("lang", "ru"))
    return {k: v[i] for k, v in S.items()}
